package com.yigongbao.backup.order;
import com.fasterxml.jackson.databind.ObjectMapper;import com.yigongbao.backup.job.*;import com.yigongbao.backup.storage.api.SpacePlanner.SpaceReservation;import com.yigongbao.backup.storage.api.SpaceReservationService;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import java.nio.file.Files;import java.nio.file.Path;
/** 将已安全落入内部暂存区的补传文件在后台校验并提交。 */
@Component @RequiredArgsConstructor public class SupplementUploadJobHandler implements JobHandler {private final SupplementService supplements;private final ObjectMapper mapper;private final SpaceReservationService reservations;@Override public void execute(JobExecutionContext x,JobEntity job)throws Exception{Payload p=mapper.readValue(job.getConfigSnapshotJson(),Payload.class);long volumeId=job.getTargetStorageVolumeId()==null?p.storageVolumeId():job.getTargetStorageVolumeId();if(volumeId<1)throw new IllegalStateException("补传任务未固化目标存储卷");Path staged=Path.of(p.stagedPath()).toRealPath();x.orderStarted(p.snapshotId(),p.snapshotId());x.fileStarted(p.snapshotId(),staged.toString(),"SUPPLEMENT",p.size());x.safePoint("SUPPLEMENT_VALIDATE",0);SpaceReservation reservation=reservations.reserve(volumeId,p.size(),job.getId());try{try(var input=Files.newInputStream(staged)){supplements.uploadForSnapshot(p.snapshotId(),p.orderCode(),p.fileName(),input,p.size(),job.getRequestedBy(),p.contentType(),p.remark(),volumeId);}Files.deleteIfExists(staged);x.fileSucceeded(p.snapshotId(),p.size());x.orderSucceeded();x.safePoint("SUPPLEMENT_COMMITTED",p.size());}finally{reservations.release(reservation);}}public record Payload(long snapshotId,String orderCode,String fileName,long size,String contentType,String remark,String stagedPath,long storageVolumeId){public Payload(long snapshotId,String orderCode,String fileName,long size,String contentType,String remark,String stagedPath){this(snapshotId,orderCode,fileName,size,contentType,remark,stagedPath,0L);}}}

